export const DICTIONARIES=Object.fromEntries(LANGUAGES.map(([lang],i)=>[lang,Object.fromEntries(Object.entries(rows).map(([key,values])=>[key,values[i]]))]));
export function deviceLanguage(value='es'){const v=value.toLowerCase();if(v.startsWith('zh'))return 'zh-Hant';return ['es','en','pt','it'].find(l=>v.startsWith(l))||'en';}
export const translator=lang=>key=>DICTIONARIES[lang]?.[key]||DICTIONARIES.es[key]||key;
